//vec3 base_color = vec3(.96, .98, 1.);
vec3 base_color = vec3(.23, .2, .2);

vec2 light0_pos = vec2(.2, .1);
vec2 light1_pos = vec2(1.5, .4);
vec2 light2_pos = vec2(.4, 1.2);

float light0_radius = .5;
float light1_radius = .7;
float light2_radius = .4;

vec3 light0_color = vec3(.44, .65, 1.);
vec3 light1_color = vec3(.72, 1., .72);
vec3 light2_color = vec3(1., .7, .3);

float factor = .5;

float dithering = .05;
float dithering_size = 3.;

float smooth_step(float t) {
    return (3. - 2.*t)*t*t;
}

float dot2(vec2 u) {
    return u.x*u.x + u.y*u.y;
}

float rand(vec2 co){ return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453); }

float get_t(float r, vec2 uv, vec2 target) {
    if (r == 0.) return 0.;

    float t = dot2(uv-target)/(r*r);

    return exp(-t-1.)*factor;
}

vec2 round_uv(vec2 uv) {
    uv *= iResolution.y;
    uv.x -= mod(uv.x, dithering_size);
    uv.y -= mod(uv.y, dithering_size);

    return uv/iResolution.y;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // uv is not normalized (sorry) to avoid stretching due to display ratio
    vec2 uv = fragCoord.xy/iResolution.y;

    float t0 = get_t(light0_radius, uv, light0_pos);
    float t1 = get_t(light1_radius, uv, light1_pos);
    float t2 = get_t(light2_radius, uv, light2_pos);

    fragColor = vec4(base_color + (light0_color-base_color)*t0 + (light1_color-base_color)*t1 + (light2_color-base_color)*t2, 1.);

    // dithering
    float mult = rand(round_uv(uv))*(dithering*2.) + 1.-dithering;
    fragColor *= mult;
}
